@T.prim_func
def main(
    A: T.Tensor((B, M, N), "float32"),
    U: T.Tensor((B, M, M), "float32"),
    S: T.Tensor((B, M), "float32"),
    VH: T.Tensor((B, N, N), "float32"),
):
    with T.Kernel(B, is_npu=True) as (cid, vid):
        with T.Scope("V"):
            if vid == 0:
                b = cid
                x_sh = T.alloc_shared([M, N], "float32")
                v_sh = T.alloc_shared([N, N], "float32")
                sigma_sh = T.alloc_shared([1, N], "float32")
                eps = 1e-6
                sweeps = 12

                for io in T.serial(4):
                    for ii in T.serial(8):
                        i = T.alloc_var("int32", init=io * 8 + ii)
                        i = io * 8 + ii
                        for j in T.serial(N):
                            x_sh[i, j] = A[b, i, j]
                            if i == j:
                                v_sh[i, j] = 1.0
                            else:
                                v_sh[i, j] = 0.0

                for j in T.serial(N):
                    sigma_sh[0, j] = 0.0

                for sweep in T.serial(sweeps):
                    for p in T.serial(N):
                        for q in T.serial(p + 1, N):
                            app = T.alloc_var("float32", init=0.0)
                            aqq = T.alloc_var("float32", init=0.0)
                            apq = T.alloc_var("float32", init=0.0)
                            app = 0.0
                            aqq = 0.0
                            apq = 0.0

                            for k in T.serial(M):
                                x_kp = T.alloc_var("float32", init=x_sh[k, p])
                                x_kq = T.alloc_var("float32", init=x_sh[k, q])
                                x_kp = x_sh[k, p]
                                x_kq = x_sh[k, q]
                                app = app + x_kp * x_kp
                                aqq = aqq + x_kq * x_kq
                                apq = apq + x_kp * x_kq

                            thresh = T.alloc_var("float32", init=eps * (app + aqq + 1.0))
                            thresh = eps * (app + aqq + 1.0)

                            rotate = T.alloc_var("int32", init=0)
                            rotate = 0
                            if apq > thresh:
                                rotate = 1
                            else:
                                if apq < -thresh:
                                    rotate = 1

                            if rotate != 0:
                                tau = T.alloc_var("float32", init=(aqq - app) / (2.0 * apq))
                                tau = (aqq - app) / (2.0 * apq)

                                sign_tau = T.alloc_var("float32", init=1.0)
                                if tau < 0.0:
                                    sign_tau = -1.0
                                else:
                                    sign_tau = 1.0

                                rad = T.alloc_var("float32", init=1.0 + tau * tau)
                                rad = 1.0 + tau * tau
                                root = T.alloc_var("float32", init=1.0)
                                if rad > 1.0:
                                    root = rad
                                else:
                                    root = 1.0
                                for _ in T.serial(8):
                                    root = 0.5 * (root + rad / root)

                                denom = T.alloc_var("float32", init=tau + sign_tau * root)
                                denom = tau + sign_tau * root

                                t = T.alloc_var("float32", init=0.0)
                                t = 0.0
                                if denom > eps:
                                    t = 1.0 / denom
                                else:
                                    if denom < -eps:
                                        t = 1.0 / denom
                                    else:
                                        t = 0.0

                                norm_sq = T.alloc_var("float32", init=1.0 + t * t)
                                norm_sq = 1.0 + t * t
                                norm = T.alloc_var("float32", init=1.0)
                                if norm_sq > 1.0:
                                    norm = norm_sq
                                else:
                                    norm = 1.0
                                for _ in T.serial(8):
                                    norm = 0.5 * (norm + norm_sq / norm)

                                c = T.alloc_var("float32", init=1.0)
                                c = 1.0
                                c = c / norm
                                s_rot = T.alloc_var("float32", init=t * c)
                                s_rot = t * c

                                for k in T.serial(M):
                                    x_kp = T.alloc_var("float32", init=x_sh[k, p])
                                    x_kq = T.alloc_var("float32", init=x_sh[k, q])
                                    x_kp = x_sh[k, p]
                                    x_kq = x_sh[k, q]
                                    x_sh[k, p] = c * x_kp - s_rot * x_kq
                                    x_sh[k, q] = s_rot * x_kp + c * x_kq

                                for k in T.serial(N):
                                    v_kp = T.alloc_var("float32", init=v_sh[k, p])
                                    v_kq = T.alloc_var("float32", init=v_sh[k, q])
                                    v_kp = v_sh[k, p]
                                    v_kq = v_sh[k, q]
                                    v_sh[k, p] = c * v_kp - s_rot * v_kq
                                    v_sh[k, q] = s_rot * v_kp + c * v_kq

                for j in T.serial(N):
                    sigma_sq = T.alloc_var("float32", init=0.0)
                    sigma_sq = 0.0
                    for i in T.serial(M):
                        x_ij = T.alloc_var("float32", init=x_sh[i, j])
                        x_ij = x_sh[i, j]
                        sigma_sq = sigma_sq + x_ij * x_ij

                    sigma = T.alloc_var("float32", init=1.0)
                    if sigma_sq > 1.0:
                        sigma = sigma_sq
                    else:
                        sigma = 1.0
                    for _ in T.serial(8):
                        sigma = 0.5 * (sigma + sigma_sq / sigma)
                    if sigma_sq == 0.0:
                        sigma = 0.0
                    sigma_sh[0, j] = sigma

                for i in T.serial(N):
                    best_idx = T.alloc_var("int32", init=i)
                    best_val = T.alloc_var("float32", init=sigma_sh[0, i])
                    best_idx = i
                    best_val = sigma_sh[0, i]

                    for j in T.serial(i + 1, N):
                        if sigma_sh[0, j] > best_val:
                            best_idx = j
                            best_val = sigma_sh[0, j]

                    if best_idx != i:
                        tmp_s = T.alloc_var("float32", init=sigma_sh[0, i])
                        tmp_s = sigma_sh[0, i]
                        sigma_sh[0, i] = sigma_sh[0, best_idx]
                        sigma_sh[0, best_idx] = tmp_s

                        for k in T.serial(M):
                            tmp_x = T.alloc_var("float32", init=x_sh[k, i])
                            tmp_x = x_sh[k, i]
                            x_sh[k, i] = x_sh[k, best_idx]
                            x_sh[k, best_idx] = tmp_x

                        for k in T.serial(N):
                            tmp_v = T.alloc_var("float32", init=v_sh[k, i])
                            tmp_v = v_sh[k, i]
                            v_sh[k, i] = v_sh[k, best_idx]
                            v_sh[k, best_idx] = tmp_v

                for i in T.serial(M):
                    for j in T.serial(N):
                        if sigma_sh[0, j] > eps:
                            U[b, i, j] = x_sh[i, j] / sigma_sh[0, j]
                        else:
                            U[b, i, j] = 0.0

                for j in T.serial(N):
                    for k in T.serial(j):
                        coeff = T.alloc_var("float32", init=0.0)
                        coeff = 0.0
                        for i in T.serial(M):
                            coeff = coeff + U[b, i, k] * U[b, i, j]
                        for i in T.serial(M):
                            U[b, i, j] = U[b, i, j] - coeff * U[b, i, k]

                    norm_sq = T.alloc_var("float32", init=0.0)
                    norm_sq = 0.0
                    for i in T.serial(M):
                        u_ij = T.alloc_var("float32", init=U[b, i, j])
                        u_ij = U[b, i, j]
                        norm_sq = norm_sq + u_ij * u_ij

                    norm = T.alloc_var("float32", init=1.0)
                    if norm_sq > 1.0:
                        norm = norm_sq
                    else:
                        norm = 1.0
                    for _ in T.serial(8):
                        norm = 0.5 * (norm + norm_sq / norm)

                    if norm > eps:
                        for i in T.serial(M):
                            U[b, i, j] = U[b, i, j] / norm
                    else:
                        for i in T.serial(M):
                            U[b, i, j] = 0.0

                for j in T.serial(N):
                    sigma = T.alloc_var("float32", init=0.0)
                    sigma = 0.0
                    for i in T.serial(M):
                        sigma = sigma + U[b, i, j] * x_sh[i, j]
                    sigma_sh[0, j] = sigma
                    S[b, j] = sigma

                for i in T.serial(N):
                    for j in T.serial(N):
                        VH[b, i, j] = v_sh[j, i]

return main
